def _send_with_retries(api_client, endpoint: str, params: Dict[str, Any], retries: int, backoff: float):
    """
    Send GET request with a lightweight retry mechanism for transient failures (>=500).
    """
    last_response = None
    for attempt in range(1, retries + 1):
        last_response = api_client.get(endpoint=endpoint, params=params)
        if last_response.status_code < 500:
            return last_response
        if attempt < retries:
            time.sleep(backoff)
    return last_response


def _parse_json_response_or_fail(response) -> Any:
    """
    Safely parse the JSON response or fail the test with a clear message.
    """
    try:
        return response.json()
    except ValueError as e:
        pytest.fail(f"Response body is not valid JSON. Status: {response.status_code}, Error: {e}, Body: {response.text[:500]}", pytrace=False)


