@pytest.mark.api
def test_search_get_table_driven(
    case: Dict[str, Any],
    api_client,
    valid_api_key: str,
    api_spec_validator: SwaggerSchemaValidator,
    request_query_schema: Dict[str, Any],
    response_200_schema: Dict[str, Any],
    response_error_schema: Dict[str, Any],
    response_fallback_schema: Dict[str, Any],
    endpoint_path: str,
    retry_settings: Tuple[int, float],
):
    """
    Table-driven test for GET /v1/search.json using cases from search.json.json.
    - Validates request against query parameter schema before sending.
    - Sends request and asserts expected status code from the test case.
    - Validates response JSON against the appropriate schema per status code.
    """
    expected_status = int(case.get("statusCode"))
    query_value = str(case.get("q", "")).strip()

    # If we expect a successful call but we don't have an API key, skip.
    # Authentication-specific tests are handled in test_authentication.py.
    if expected_status == 200 and not valid_api_key:
        pytest.skip("Valid API key is required for 200 success scenarios. Skipping due to missing key.")

    # Build query params strictly from test case
    params: Dict[str, Any] = {"q": query_value}
    if valid_api_key:
        params["key"] = valid_api_key

    # Validate request parameters before sending
    api_spec_validator.validate_with_schema(params, request_query_schema)

    # Send request with retries for transient server errors
    retries, backoff = retry_settings
    response = _send_with_retries(api_client, endpoint_path, params, retries=retries, backoff=backoff)

    # Status code assertion based on the test case data
    assert response.status_code == expected_status, (
        f"Unexpected status code for q='{query_value}'. "
        f"Expected: {expected_status}, Actual: {response.status_code}, Body: {response.text[:500]}"
    )

    # Attempt JSON parsing
    json_data = _parse_json_response_or_fail(response)

    # Validate response against appropriate schema using validator
